contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(bool shouldFinish) public payable {
        bool before = c.distributionFinished(); if (__ESBMC_reverted()) return;
        bool success;
        c.finishDistribution(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { success = false; } else { success = true; }
        assert(success ? c.distributionFinished() == true : c.distributionFinished() == before);
    }
}

