// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(bool shouldFinish) internal {
        bool before;
        try c.distributionFinished() returns (bool __r) { before = __r; } catch { return; }
        bool success;
        try c.finishDistribution() { success = true; } catch { success = false; }
        assertTrue(success ? c.distributionFinished() == true : c.distributionFinished() == before);
    }

    function testFuzz_run(bool shouldFinish) public {
        _run(shouldFinish);
    }

    receive() external payable {}
}
